<div class="admin-head"><div><span class="eyebrow">CATÁLOGO</span><h2 class="section">Administración de productos</h2></div><a class="btn grad" href="/?r=productForm">+ Agregar producto</a></div><div class="report-actions mb-3"><a class="btn grad" href="/?<?=e(http_build_query(array_merge($_GET,['r'=>'exportModule','module'=>'products','type'=>'pdf'])))?>">Exportar PDF</a><a class="btn blue" href="/?<?=e(http_build_query(array_merge($_GET,['r'=>'exportModule','module'=>'products','type'=>'excel'])))?>">Exportar Excel</a></div><form class="filter-strip" method="get"><input type="hidden" name="r" value="adminProducts"><input class="form-control" name="q" placeholder="Nombre, SKU o marca" value="<?=e($_GET['q']??'')?>"><select class="form-select searchable-select" name="category"><option value="">Todas las categorías</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=($_GET['category']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select class="form-select searchable-select" name="status"><option value="">Todos los estados</option><option value="activo" <?=($_GET['status']??'')==='activo'?'selected':''?>>Activo</option><option value="inactivo" <?=($_GET['status']??'')==='inactivo'?'selected':''?>>Inactivo</option></select><button class="btn blue">Filtrar</button></form><div class="card p-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Producto</th><th>SKU</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><div class="d-flex align-items-center gap-2"><img class="cart-thumb" src="/<?=e($p['image'])?>"><div><b><?=e($p['name'])?></b><small class="d-block text-muted"><?=e($p['brand'])?></small></div></div></td><td><?=e($p['sku'])?></td><td><?=e($p['category'])?></td><td>Q<?=number_format((float)$p['sale_price']>0?$p['sale_price']:$p['price'],2)?></td><td><?=$p['stock']?></td><td><?=e($p['status'])?></td><td><a class="btn soft btn-sm" href="/?r=productForm&id=<?=$p['id']?>">Editar</a></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../_pagination.php';?></div>